# Routing constants — extracted from inline magic numbers in v30 Trader.run.
HP_TS0_BID_RANGE              = (10001, 10005)  # day-2 fingerprint at ts==0
DP_FINGERPRINT_CUTOFF_TS      = 80_000          # past this ts, DP catch-up > remaining gain
DP_TICK_LIMIT                 = 1_000           # DP path ends here (= 100k ts)
FINGERPRINT_CONSEC_REQUIRED   = 3               # consecutive HP-mid matches to commit DP
DRIFT_MISS_THRESHOLD          = 3               # consecutive misses to abort DP -> LIVE

# ===== Per-product drift guard tables =====
# Per-product (best_bid + best_ask) tables, delta-encoded.
# Format: (base_int, 'd1,d2,d3,...') -- use _decode() to expand.

def _decode(base, deltas_str):
    deltas = [int(d) for d in deltas_str.split(',')] if deltas_str else []
    return list(accumulate([base, *deltas]))

